//! `OpenAPI` 3.1 document + Scalar try-it-out, and the `AsyncAPI` 3.0 document
//! (feature `openapi`, default on).
//!
//! Per ADR-W002 the REST spec is code-first via utoipa (verified `OpenAPI` 3.1
//! only). [`ApiDoc`] aggregates the path + schema definitions; [`openapi_router`]
//! serves the document at `/api/v1/openapi.json` and the Scalar UI at `/docs`.
//!
//! The realtime spec (`AsyncAPI` 3.0) is generated by `cargo xtask gen-asyncapi`
//! and committed to `docs/api/asyncapi.json`. It is embedded at compile time with
//! `include_str!` and served at `/asyncapi.json` — alongside the REST spec, not
//! under `/api/v1` (the realtime surface is transport-level, not REST-resource).
use axum::extract::State;
use axum::http::header;
use axum::response::IntoResponse;
use axum::Json;
use axum::Router;
use utoipa::openapi::security::{HttpAuthScheme, HttpBuilder, SecurityScheme};
use utoipa::{Modify, OpenApi};
use utoipa_scalar::{Scalar, Servable};

use crate::state::AppState;

/// Registers the reusable `bearer_auth` security scheme (HTTP Bearer) in the
/// document components so authenticated operations can reference it with
/// `security(("bearer_auth" = []))`. The scheme covers both machine bearers the
/// control plane accepts — a hashed API key and a JWT — carried as
/// `Authorization: Bearer <token>` (ADR-W004). Applied via `modifiers(...)` below.
///
/// No *global* `security` requirement is set: only the operations that annotate
/// their own `security` advertise it, so unauthenticated routes (health,
/// `/auth/status`) are not falsely marked as requiring a credential.
struct SecurityAddon;

impl Modify for SecurityAddon {
    fn modify(&self, openapi: &mut utoipa::openapi::OpenApi) {
        // `components` is always present once schemas are registered above, but
        // create it defensively rather than unwrap (no panics in library code).
        let components = openapi.components.get_or_insert_with(Default::default);
        components.add_security_scheme(
            "bearer_auth",
            SecurityScheme::Http(
                HttpBuilder::new()
                    .scheme(HttpAuthScheme::Bearer)
                    .description(Some(
                        "Machine bearer token: a hashed API key or a JWT, sent as \
                         `Authorization: Bearer <token>`.",
                    ))
                    .build(),
            ),
        );
    }
}

/// The `AsyncAPI` 3.0 document, embedded at compile time from the generated
/// file produced by `cargo xtask gen-asyncapi`. Served as-is; the `xtask` is
/// the authoritative generator and the JSON is committed to version control so
/// the binary is self-contained without a runtime filesystem dependency.
///
/// Path is relative to `crates/multiview-control/` (the crate root).
const ASYNCAPI_JSON: &str = include_str!("../../../docs/api/asyncapi.json");

